function randomBase64Url() {
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    var result = "";

    // 16字节 -> Base64URL 24字符，末尾==
    for (var i = 0; i < 22; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length));
    }

    return result + "==";
}

function hmac256(data, key) {
    return CryptoJS.HmacSHA256(data, key).toString(CryptoJS.enc.Hex);
}
function randomDeviceId() {
    var hex = "0123456789abcdef";
    var s = "";
    for (var i = 0; i < 32; i++) {
        s += hex.charAt(Math.floor(Math.random() * 16));
    }
    return s;
}



function makeSign(method, path,host) {

    // 拆分 path 和 query
    var p = path;
    var query = "";

    var i = path.indexOf("?");
    if (i !== -1) {
        p = path.substring(0, i);
        query = path.substring(i + 1);
    }
    var host = host || getMyVar("host")
    var secret = "cms_device_salt_v1_2024cms_app_sign_key_v1_2024_secure";

    var deviceid =randomDeviceId()
    // deviceId -> HMAC
    var deviceSign = hmac256(deviceid, secret);
    var nonce =randomBase64Url();
    var appversion = "1.0.19+20";
    var timestamp= Math.floor(Date.now() / 1000);
    var url = host+path 
    // 拼接待签名字符串
    var str = [
        method.toUpperCase(),
        p,
        query,
        String(timestamp),
        nonce,
        appversion
    ].join("\n");

    // 最终签名
    var sign = hmac256(str, deviceSign);
    var headers  = {
        "x-signature": sign,
        "x-nonce":nonce,
        "x-timestamp":String(timestamp),
        "x-device-id":deviceid,
        "x-app-version":appversion

    }
    return {


        url: url,
        headers:headers

    };
}

function combinPath(dire, path) {
    let Proto = '';
    if (dire.includes("//")) {
        [Proto, _, dire] = dire.split(/(\/{2})/);
        Proto += _;
    }
    const Paths = java.nio.file.Paths;
    dire = dire + path;
    var p = Paths.get(dire).toAbsolutePath().normalize();
    return Proto + String(p);
}



